TEMPLATE_SOURCE = '<!doctype html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width,initial-scale=1">\n  <meta name="color-scheme" content="light dark">\n  <meta name="robots" content="{{ robots_content }}">\n  <script>\n    try {\n      const theme = localStorage.getItem("xunxian-color-theme");\n      if (theme === "orange" || theme === "dark") document.documentElement.dataset.theme = "orange";\n      if (theme === "dark") document.documentElement.dataset.mode = "dark";\n    } catch {}\n  </script>\n  <link rel="canonical" href="{{ canonical_url }}">\n  <title>{% if detail %}{{ detail.summary.quest_name }} · {% endif %}寻仙任务存档</title>\n  <link rel="icon" href="/static/logo.png" type="image/png">\n  <link rel="stylesheet" href="/static/styles.css?v=20261118-v111-rowfit2">\n  <script src="/static/app.js?v=20261118-v111-rowfit2" defer></script>\n</head>\n<body>\n  <a class="skip-link" href="#quest-dossier">跳到任务正文</a>\n  <header class="topbar">\n    <a class="brand" href="/" aria-label="寻仙任务存档首页">\n      <img class="brand-mark" src="/static/logo.png" alt="" width="32" height="32">\n      <span class="brand-copy">\n        <strong>寻仙任务存档</strong>\n      </span>\n    </a>\n    <div class="topbar-status">\n      <button class="topbar-version" type="button" data-open-about aria-haspopup="dialog" aria-label="关于寻仙任务存档，版本 v{{ site_version }}">v{{ site_version }}</button>\n      <div class="theme-picker" role="group" aria-label="颜色主题">\n        <button type="button" class="theme-swatch" data-theme-value="green" aria-label="青绿主题" aria-pressed="true" title="青绿主题"></button>\n        <button type="button" class="theme-swatch" data-theme-value="orange" aria-label="陶土橙主题" aria-pressed="false" title="陶土橙主题"></button>\n        <button type="button" class="theme-swatch" data-theme-value="dark" aria-label="深色主题" aria-pressed="false" title="深色主题"></button>\n      </div>\n      <span class="topbar-visitors">今日来访 <strong id="today-visitors">{{ today_visitors }}</strong></span>\n    </div>\n  </header>\n\n  <dialog class="about-dialog" id="about-dialog" aria-labelledby="about-title">\n    <h3 id="about-title" class="about-dialog-head">寻仙任务存档 v{{ site_version }}</h3>\n    <div class="about-dialog-body">\n      <div class="about-row">\n        <svg class="is-fill" viewBox="0 0 16 16" aria-hidden="true"><path d="M8 0C3.58 0 0 3.58 0 8c0 3.54 2.29 6.53 5.47 7.59.4.07.55-.17.55-.38 0-.19-.01-.82-.01-1.49-2.01.37-2.53-.49-2.69-.94-.09-.23-.48-.94-.82-1.13-.28-.15-.68-.52-.01-.53.63-.01 1.08.58 1.23.82.72 1.21 1.87.87 2.33.66.07-.52.28-.87.51-1.07-1.78-.2-3.64-.89-3.64-3.95 0-.87.31-1.59.82-2.15-.08-.2-.36-1.02.08-2.12 0 0 .67-.21 2.2.82.64-.18 1.32-.27 2-.27.68 0 1.36.09 2 .27 1.53-1.04 2.2-.82 2.2-.82.44 1.1.16 1.92.08 2.12.51.56.82 1.27.82 2.15 0 3.07-1.87 3.75-3.65 3.95.29.25.54.73.54 1.48 0 1.07-.01 1.93-.01 2.2 0 .21.15.46.55.38A8.013 8.013 0 0 0 16 8c0-4.42-3.58-8-8-8Z"/></svg>\n        <span class="about-label">项目地址</span>\n        <a href="https://github.com/icosohedral/xunxian-quests-archive" target="_blank" rel="noopener noreferrer" title="github.com/icosohedral/xunxian-quests-archive">xunxian-quests-archive</a>\n      </div>\n      <div class="about-row">\n        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m16.24 7.76-1.804 5.411a2 2 0 0 1-1.265 1.265L7.76 16.24l1.804-5.411a2 2 0 0 1 1.265-1.265z"/><circle cx="12" cy="12" r="10"/></svg>\n        <span class="about-label">资源总站</span>\n        <a href="https://xunxian.wiki" target="_blank" rel="noopener noreferrer">xunxian.wiki</a>\n      </div>\n      <p class="about-notice">本站为任务资料整理项目，游戏及相关权利归原权利人所有。</p>\n    </div>\n    <div class="about-dialog-foot">\n      <button type="button" class="about-dialog-ok" data-close-about autofocus>知道了</button>\n    </div>\n  </dialog>\n\n  <main class="workbench">\n    <aside class="search-rail" id="search-rail" aria-label="任务检索">\n      <div class="rail-heading">\n        <div>\n          <span class="eyebrow">QUEST INDEX</span>\n          <h1>任务检索</h1>\n        </div>\n        <button class="icon-button mobile-close" type="button" data-close-sheet="search-rail" aria-label="关闭检索">×</button>\n      </div>\n\n      <form class="search-form" action="/" method="get">\n        <label class="search-box">\n          <span class="sr-only">任务名称</span>\n          <input name="q" value="{{ filters.q }}" placeholder="输入任务名称" autocomplete="off">\n          <button type="submit" aria-label="搜索"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg></button>\n        </label>\n        {% set active_filter_count = [filters.npc, filters.area, filters.category, filters.subcategory]|select|list|length %}\n        {% set panel_open = active_filter_count if filter_panel_open is none else filter_panel_open %}\n        <details class="filter-panel" id="filter-panel" {% if panel_open %}open{% endif %}>\n          <summary>\n            <span>筛选条件</span>\n            <span class="filter-count" id="filter-count" {% if not active_filter_count %}hidden{% endif %}>{{ active_filter_count }}</span>\n            <svg viewBox="0 0 16 16" aria-hidden="true"><path d="m4 6 4 4 4-4"/></svg>\n          </summary>\n        <div class="filter-grid">\n          <label>\n            <span>NPC</span>\n            <input name="npc" value="{{ filters.npc }}">\n          </label>\n          <label>\n            <span>地区</span>\n            <select name="area">\n              <option value="">全部地区</option>\n              {% for area_option in facets.areas %}\n                <option value="{{ area_option.name }}" {% if filters.area == area_option.name %}selected{% endif %}>{{ area_option.name }}</option>\n              {% endfor %}\n            </select>\n          </label>\n          <label>\n            <span>主类型</span>\n            <select name="category" id="main-category">\n              <option value="">全部主类型</option>\n              {% for category_option in facets.categories %}\n                <option value="{{ category_option.name }}" {% if filters.category == category_option.name %}selected{% endif %}>{{ category_option.name }}（{{ category_option.task_count }}）</option>\n              {% endfor %}\n            </select>\n          </label>\n          <label>\n            <span>子类型</span>\n            <select name="subcategory" id="sub-category" {% if not filters.category %}disabled{% endif %}>\n              <option value="">全部子类型</option>\n              {% for subcategory_option in facets.subcategories %}\n                <option\n                  value="{{ subcategory_option.name }}"\n                  data-parent="{{ subcategory_option.parent_name }}"\n                  {% if filters.category != subcategory_option.parent_name %}hidden disabled{% endif %}\n                  {% if filters.category == subcategory_option.parent_name and filters.subcategory == subcategory_option.name %}selected{% endif %}\n                >{{ subcategory_option.name }}（{{ subcategory_option.task_count }}）</option>\n              {% endfor %}\n            </select>\n          </label>\n        </div>\n        </details>\n        <div class="form-actions">\n          <button class="primary-button" type="submit">检索任务</button>\n          <a class="text-link" href="/">清除条件</a>\n        </div>\n      </form>\n\n      <div class="result-heading" id="search-result-heading">\n        <span>检索结果</span>\n        <small id="search-result-summary">{{ search.total }} 条{% if search.search_active %} · 总经验 {{ search.total_experience|compact_number }}{% endif %}</small>\n      </div>\n\n      <div class="quest-list" id="search-result-list" data-page-size="{{ search.page_size }}"{% if list_row_height %} style="--quest-card-height: {{ list_row_height }}px"{% endif %} aria-live="polite">\n        {% for quest in search["items"] %}\n          <a\n            class="quest-card {% if detail and detail.summary.quest_id == quest.quest_id %}is-active{% endif %}"\n            href="/?selected={{ quest.quest_id }}&q={{ filters.q|urlencode }}&npc={{ filters.npc|urlencode }}&area={{ filters.area|urlencode }}&category={{ filters.category|urlencode }}&subcategory={{ filters.subcategory|urlencode }}&page={{ search.page }}"\n            data-recent-quest="{{ quest.quest_id }}"\n          >\n            <strong>{{ quest.quest_name }}</strong>\n          </a>\n        {% else %}\n          <div class="empty-state">\n            <span aria-hidden="true">⌁</span>\n            <strong>没有找到任务</strong>\n            <p>换一个任务名称、NPC、地区或任务类型试试。</p>\n          </div>\n        {% endfor %}\n      </div>\n\n      <nav class="pagination" id="search-pagination" aria-label="任务列表分页">\n        <a href="{{ prev_url }}" aria-disabled="{{ \'true\' if search.page <= 1 else \'false\' }}">上一页</a>\n        <span>{{ search.page }} / {{ search.page_count }}</span>\n        <a href="{{ next_url }}" aria-disabled="{{ \'true\' if search.page >= search.page_count else \'false\' }}">下一页</a>\n      </nav>\n    </aside>\n\n    <section class="dossier" id="quest-dossier" tabindex="-1">\n      {% if detail %}\n        <div class="dossier-intro">\n          <div>\n            <span class="eyebrow">QUEST DOSSIER</span>\n            <h2>{{ detail.summary.quest_name }}</h2>\n            {% if detail.aliases %}\n              <p class="alias-line">别名：{{ detail.aliases|join("、") }}</p>\n            {% endif %}\n          </div>\n          <div class="dossier-badges">\n            {% if detail.safe_display_merge %}\n              <span class="badge badge-brass">重复记录无损合并 ×{{ detail.variants|length }}</span>\n            {% endif %}\n          </div>\n        </div>\n\n        <dl class="quest-facts">\n          <div><dt>等级</dt><dd>{{ detail.summary.level_requirement if detail.summary.level_requirement is not none else "—" }}</dd></div>\n          <div><dt>接取 NPC</dt><dd>{% if detail.accept_role %}<button\n            class="role-trigger"\n            type="button"\n            data-evidence=\'{{ detail.accept_role|tojson }}\'\n          >{{ detail.accept_role.label }}</button>{% else %}{{ detail.summary.accept_object_name or "未解析" }}{% endif %}</dd></div>\n          <div><dt>提交 NPC</dt><dd>{% if detail.submit_role %}<button\n            class="role-trigger"\n            type="button"\n            data-evidence=\'{{ detail.submit_role|tojson }}\'\n          >{{ detail.submit_role.label }}</button>{% else %}{{ detail.summary.submit_object_name or "未解析" }}{% endif %}</dd></div>\n          <div><dt>所属地区</dt><dd>{{ detail.summary.area_name or "未记录" }}</dd></div>\n          <div><dt>任务类型</dt><dd>{{ detail.summary.main_category_name or detail.summary.category_id or "未记录" }}{% if detail.summary.sub_category_name and detail.summary.sub_category_name != "未分类" %} · {{ detail.summary.sub_category_name }}{% endif %}</dd></div>\n        </dl>\n\n        <section class="text-ledger" aria-labelledby="text-heading">\n          <div class="section-heading">\n            <div>\n              <span class="eyebrow">QUEST SCRIPT</span>\n              <h3 id="text-heading">任务文本</h3>\n            </div>\n            {% if detail.text_sections|rejectattr("is_empty")|list %}\n              <button class="copy-text-button" type="button" data-copy-text aria-label="复制当前标签下的文字" title="复制当前标签下的文字">\n                <svg class="copy-icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="9" width="11" height="11" rx="2"/><path d="M5 15V6a2 2 0 0 1 2-2h9"/></svg>\n                <svg class="copied-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>\n                <span class="copy-text-status" aria-live="polite"></span>\n              </button>\n            {% endif %}\n          </div>\n          {% set filled_sections = detail.text_sections|rejectattr("is_empty")|list %}\n          {% if filled_sections %}\n          <div class="text-tabs" role="tablist" aria-label="任务文本类型">\n            {% for section in filled_sections %}\n              <button\n                type="button"\n                role="tab"\n                id="tab-{{ section.field }}"\n                aria-controls="panel-{{ section.field }}"\n                aria-selected="{{ \'true\' if loop.first else \'false\' }}"\n                tabindex="{{ \'0\' if loop.first else \'-1\' }}"\n                data-tab="{{ section.field }}"\n              >{{ section.label }}</button>\n            {% endfor %}\n          </div>\n          {% for section in filled_sections %}\n            <article\n              class="text-panel"\n              id="panel-{{ section.field }}"\n              role="tabpanel"\n              aria-labelledby="tab-{{ section.field }}"\n              {% if not loop.first %}hidden{% endif %}\n            >\n              <p class="quest-prose">{% for token in section.tokens %}{% if token.type == "text" %}{{ token.value }}{% else %}<button\n                  class="entity-tag entity-tag--{{ token.resolution.kind }} entity-tag--{{ token.resolution.status }}"\n                  type="button"\n                  data-evidence=\'{{ token.resolution|tojson }}\'\n                ><span>{{ {"enemy":"敌人","target":"目标","item":"道具","hint":"提示","character":"称谓","friend":"角色"}.get(token.resolution.kind, "标签") }}</span>{{ token.resolution.label }}</button>{% endif %}{% endfor %}</p>\n            </article>\n          {% endfor %}\n          {% else %}\n            <p class="field-empty">原始数据为空，这条任务没有任何文本记录</p>\n          {% endif %}\n        </section>\n\n        <div class="detail-columns">\n          <section class="data-section">\n            <div class="section-heading compact">\n              <div><span class="eyebrow">OBJECTIVES</span><h3>条件与目标</h3></div>\n            </div>\n            {% if detail.conditions %}\n              <div class="condition-list">\n                {% for item in detail.conditions %}\n                  <div class="condition-row">\n                    <span class="object-icon">前</span>\n                    <div>\n                      <strong>{% if item.object_type_id == 5 and item.object_id is not none %}<a\n                        class="condition-quest-link"\n                        href="/?selected={{ item.object_id }}{% if preserved_query %}&{{ preserved_query }}{% endif %}"\n                      >{{ item.object_name or ("任务 " ~ item.object_id) }}</a>{% elif item.object_type_id in (2, 21) and item.object_id is not none and item.object_name %}<a\n                        class="resource-detail-link"\n                        href="https://xunxian.wiki/resources/{{ \'quest_item\' if item.object_type_id == 2 else \'title\' }}/{{ item.object_id }}"\n                        target="_blank"\n                        rel="noopener noreferrer"\n                      >{% if item.object_type_id == 21 %}称号 {% endif %}{{ item.object_name }}</a>{% elif item.object_name %}{% if item.object_type_id == 20 %}状态 {% elif item.object_type_id == 21 %}称号 {% elif item.object_type_id == 22 %}称号组 {% endif %}{{ item.object_name }}{% elif item.object_id is not none %}{{ item.object_type_name or "对象" }} {{ item.object_id }}{% else %}未确认条件组{% endif %}</strong>\n                    </div>\n                  </div>\n                {% endfor %}\n              </div>\n            {% endif %}\n            {% if detail.objectives %}\n              <div class="objective-list">\n                {% for item in detail.objectives %}\n                  <div class="objective-row">\n                    <span class="object-icon object-icon--red">目</span>\n                    <div>\n                      <strong>{% if item.role_resolution %}<button\n                        class="role-trigger role-trigger--objective"\n                        type="button"\n                        data-evidence=\'{{ item.role_resolution|tojson }}\'\n                      >{{ item.role_resolution.label }}</button>{% elif item.object_type_id == 2 and item.object_id is not none and item.object_name %}<a\n                        class="resource-detail-link"\n                        href="https://xunxian.wiki/resources/quest_item/{{ item.object_id }}"\n                        target="_blank"\n                        rel="noopener noreferrer"\n                      >{{ item.object_name }}</a>{% else %}{{ item.object_name or (item.object_type_name ~ " " ~ item.object_id) }}{% endif %}</strong>\n                    </div>\n                    <b>×{{ item.amount }}</b>\n                  </div>\n                {% endfor %}\n              </div>\n            {% else %}\n              <p class="field-empty compact-empty">没有结构化任务目标</p>\n            {% endif %}\n          </section>\n\n          <section class="data-section">\n            <div class="section-heading compact">\n              <div><span class="eyebrow">REWARDS</span><h3>任务奖励</h3></div>\n            </div>\n            {% if detail.rewards %}\n              <div class="reward-grid">\n                {% for reward in detail.rewards %}\n                  <div class="reward-card">\n                    <span>{% if reward.object_type_id == 21 %}称号{% elif reward.object_type_id == 22 %}称号组{% elif reward.object_type_name == "阵营" %}阵营声望{% else %}{{ reward.object_type_name or "对象" }}{% endif %}</span>\n                    <strong>{% if reward.object_type_id in (2, 21) and reward.object_id is not none and reward.object_name %}<a\n                      class="resource-detail-link"\n                      href="https://xunxian.wiki/resources/{{ \'item\' if reward.object_type_id == 2 else \'title\' }}/{{ reward.object_id }}"\n                      target="_blank"\n                      rel="noopener noreferrer"\n                    >{{ reward.object_name }}</a>{% else %}{{ reward.object_name or ("ID " ~ reward.object_id) }}{% endif %}</strong>\n                    <b>{{ "+" if reward.object_type_name in ("阵营", "经验值") else "×" }}{{ reward.amount|compact_number }}</b>\n                  </div>\n                {% endfor %}\n              </div>\n            {% else %}\n              <p class="field-empty compact-empty">没有结构化奖励记录</p>\n            {% endif %}\n          </section>\n        </div>\n      {% else %}\n        <div class="empty-dossier">\n          <span aria-hidden="true">卷</span>\n          <h2>选择一项任务开始查看</h2>\n          <p>左侧可以按任务名称、NPC、地区或分类检索。</p>\n        </div>\n      {% endif %}\n    </section>\n\n    <aside class="context-rail" id="context-rail" aria-label="任务语境">\n      <div class="rail-heading">\n        <div>\n          <span class="eyebrow">CONTEXT</span>\n          <h2>任务语境</h2>\n        </div>\n        <button class="icon-button mobile-close" type="button" data-close-sheet="context-rail" aria-label="关闭关系面板">×</button>\n      </div>\n      {% if detail %}\n        {% set incoming_next = detail.relations.incoming|selectattr("relation_type", "equalto", "next")|list %}\n        {% set outgoing_next = detail.relations.outgoing|selectattr("relation_type", "equalto", "next")|list %}\n        {% set incoming_confirmed = detail.relations.incoming|selectattr("relation_type", "equalto", "completion_requirement")|list %}\n        {% set outgoing_confirmed = detail.relations.outgoing|selectattr("relation_type", "equalto", "completion_requirement")|list %}\n        {% set incoming_updates = detail.relations.incoming|selectattr("relation_type", "equalto", "version_update")|list %}\n        {% set outgoing_updates = detail.relations.outgoing|selectattr("relation_type", "equalto", "version_update")|list %}\n        {% set incoming_context = incoming_next + incoming_confirmed + incoming_updates %}\n        {% set outgoing_context = outgoing_next + outgoing_confirmed + outgoing_updates %}\n        {% if incoming_context or outgoing_context %}\n        <section class="context-section">\n          <div class="context-title">\n            <h3>任务关系</h3>\n          </div>\n          <div class="relation-graph" role="img" aria-label="任务之间的直接关系">\n            {% if incoming_context %}\n              {% for relation in incoming_context %}\n                <a class="relation-node relation-node--muted" href="/?selected={{ relation.from_quest_id }}{% if preserved_query %}&{{ preserved_query }}{% endif %}"{% if relation.inference_basis %} title="{{ relation.inference_basis }}"{% endif %}>\n                  <strong>{{ relation.from_quest_name }}</strong>\n                </a>\n              {% endfor %}\n              <span class="relation-line" aria-hidden="true"></span>\n            {% endif %}\n            <div class="relation-node relation-node--current">\n              <strong>{{ detail.summary.quest_name }}</strong>\n            </div>\n            {% if outgoing_context %}\n              <span class="relation-line" aria-hidden="true"></span>\n              {% for relation in outgoing_context %}\n                <a class="relation-node" href="/?selected={{ relation.to_quest_id }}{% if preserved_query %}&{{ preserved_query }}{% endif %}"{% if relation.inference_basis %} title="{{ relation.inference_basis }}"{% endif %}>\n                  <strong>{{ relation.to_quest_name or "未找到任务" }}</strong>\n                </a>\n              {% endfor %}\n            {% endif %}\n          </div>\n        </section>\n        {% endif %}\n\n        <section class="context-section related-section" aria-live="polite">\n          <div class="context-title">\n            <h3>相关任务</h3>\n            <span id="related-count"></span>\n          </div>\n          <div\n            class="related-quests"\n            id="related-quests"\n            data-preserved-query="{{ preserved_query }}"\n          >\n            <div class="related-empty">点击任务中的角色，查看它参与的其他任务。</div>\n          </div>\n        </section>\n\n        <section class="context-section evidence-section" aria-live="polite">\n          <div class="context-title">\n            <h3>对象详情</h3>\n          </div>\n          <div\n            class="evidence-card"\n            id="evidence-card"\n            {% if detail.default_evidence %}data-default-evidence=\'{{ detail.default_evidence|tojson }}\'{% endif %}\n          >\n            <div class="evidence-empty" id="evidence-empty" {% if detail.default_evidence %}hidden{% endif %}>\n              点击任务正文中的对象标签，查看它连接到哪条数据。\n            </div>\n            <dl id="evidence-list" {% if not detail.default_evidence %}hidden{% endif %}></dl>\n          </div>\n        </section>\n      {% endif %}\n    </aside>\n  </main>\n\n  <nav class="mobile-dock" aria-label="移动端面板">\n    <button type="button" data-open-sheet="search-rail">检索</button>\n    <a href="#quest-dossier">任务正文</a>\n    <button type="button" data-open-sheet="context-rail">任务语境</button>\n  </nav>\n  <div class="sheet-backdrop" data-sheet-backdrop hidden></div>\n</body>\n</html>\n'
